CREATE TABLE departments(id BIGINT PRIMARY KEY,name VARCHAR(100) NOT NULL);
CREATE TABLE classes(id BIGINT PRIMARY KEY,dept_id BIGINT NOT NULL,name VARCHAR(100) NOT NULL,major VARCHAR(100) NOT NULL,grade INT NOT NULL,FOREIGN KEY(dept_id) REFERENCES departments(id));
CREATE TABLE users(id BIGINT PRIMARY KEY AUTO_INCREMENT,account VARCHAR(32) NOT NULL UNIQUE,name VARCHAR(50) NOT NULL,password_hash VARCHAR(100) NOT NULL,role VARCHAR(20) NOT NULL,dept_id BIGINT NOT NULL,class_id BIGINT,enabled BOOLEAN NOT NULL DEFAULT TRUE,seat_no INT,FOREIGN KEY(dept_id) REFERENCES departments(id),FOREIGN KEY(class_id) REFERENCES classes(id),CHECK(role IN ('student','teacher','counselor','vice','dean')));
CREATE TABLE rosters(account VARCHAR(32) PRIMARY KEY,name VARCHAR(50) NOT NULL,class_id BIGINT NOT NULL,claimed BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE courses(id BIGINT PRIMARY KEY,name VARCHAR(100) NOT NULL,teacher_id BIGINT NOT NULL,class_id BIGINT NOT NULL,room VARCHAR(100) NOT NULL,FOREIGN KEY(teacher_id) REFERENCES users(id),FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE lessons(id BIGINT PRIMARY KEY AUTO_INCREMENT,course_id BIGINT NOT NULL,lesson_date DATE NOT NULL,period_no INT NOT NULL,start_at DATETIME(6) NOT NULL,end_at DATETIME(6) NOT NULL,UNIQUE(course_id,lesson_date,period_no),FOREIGN KEY(course_id) REFERENCES courses(id),CHECK(end_at>start_at));
CREATE TABLE tokens(token_hash CHAR(64) PRIMARY KEY,user_id BIGINT NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE attendance(session_id BIGINT NOT NULL,student_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL,checked_at DATETIME(6),PRIMARY KEY(session_id,student_id),FOREIGN KEY(session_id) REFERENCES lessons(id),FOREIGN KEY(student_id) REFERENCES users(id),CHECK(status IN ('PRESENT','LATE','ABSENT','LEAVE')));
CREATE TABLE hands(session_id BIGINT NOT NULL,student_id BIGINT NOT NULL,raised BOOLEAN NOT NULL,PRIMARY KEY(session_id,student_id),FOREIGN KEY(session_id) REFERENCES lessons(id),FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE messages(id BIGINT PRIMARY KEY AUTO_INCREMENT,session_id BIGINT NOT NULL,sender_id BIGINT NOT NULL,receiver_id BIGINT,body VARCHAR(2000) NOT NULL,created_at DATETIME(6) NOT NULL,FOREIGN KEY(session_id) REFERENCES lessons(id),FOREIGN KEY(sender_id) REFERENCES users(id),FOREIGN KEY(receiver_id) REFERENCES users(id));
CREATE TABLE scores(session_id BIGINT NOT NULL,student_id BIGINT NOT NULL,score INT NOT NULL,remark VARCHAR(1000) NOT NULL,PRIMARY KEY(session_id,student_id),FOREIGN KEY(session_id) REFERENCES lessons(id),FOREIGN KEY(student_id) REFERENCES users(id),CHECK(score BETWEEN 0 AND 100));
CREATE TABLE attachments(id BIGINT PRIMARY KEY AUTO_INCREMENT,owner_id BIGINT NOT NULL,name VARCHAR(200) NOT NULL,media_type VARCHAR(30) NOT NULL,content MEDIUMBLOB NOT NULL,FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE leave_applications(id BIGINT PRIMARY KEY AUTO_INCREMENT,student_id BIGINT NOT NULL,type VARCHAR(20) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,span_days INT NOT NULL,reason VARCHAR(2000) NOT NULL,attachment_id BIGINT,status VARCHAR(30) NOT NULL,stage INT NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL,FOREIGN KEY(student_id) REFERENCES users(id),FOREIGN KEY(attachment_id) REFERENCES attachments(id),CHECK(end_date>=start_date));
CREATE TABLE leave_targets(application_id BIGINT NOT NULL,session_id BIGINT NOT NULL,PRIMARY KEY(application_id,session_id),FOREIGN KEY(application_id) REFERENCES leave_applications(id),FOREIGN KEY(session_id) REFERENCES lessons(id));
CREATE TABLE teacher_reviews(application_id BIGINT NOT NULL,teacher_id BIGINT NOT NULL,decision VARCHAR(20) NOT NULL DEFAULT 'PENDING',PRIMARY KEY(application_id,teacher_id),FOREIGN KEY(application_id) REFERENCES leave_applications(id),FOREIGN KEY(teacher_id) REFERENCES users(id));
CREATE TABLE audit_logs(id BIGINT PRIMARY KEY AUTO_INCREMENT,actor_id BIGINT NOT NULL,action VARCHAR(80) NOT NULL,target_id BIGINT NOT NULL,before_value VARCHAR(100),after_value VARCHAR(100),reason VARCHAR(2000) NOT NULL,created_at DATETIME(6) NOT NULL,FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE notifications(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,body VARCHAR(500) NOT NULL,created_at DATETIME(6) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE reset_requests(id BIGINT PRIMARY KEY AUTO_INCREMENT,account VARCHAR(32) NOT NULL,created_at DATETIME(6) NOT NULL);
